const rtdal002578Source0019 = `abort_lossy_cast <- function(x, to, ..., lossy) {
  problems <- which(lossy)
  if (is_empty(problems)) {
    return()
  }

  abort(
    paste0(
      "Lossy cast from <character> to <hms> at position(s) ",
      commas(problems)
    )
  )
}`

const rtdal002578Source0020 = `commas <- function(problems) {
  MAX_BULLETS <- 6L
  if (length(problems) >= MAX_BULLETS) {
    n_more <- length(problems) - MAX_BULLETS + 1L
    problems[[MAX_BULLETS]] <-
      paste0(pre_dots("(and "), n_more, " more)")
    length(problems) <- MAX_BULLETS
  }

  paste0(problems, collapse = ", ")
}`

const rtdal002578Source0021 = `pre_dots <- function(x) {
  if (length(x) > 0) {
    paste0("... ", x)
  } else {
    character()
  }
}`

