const rtdal002605Source0001 = "parseCssColors <- function(str, mustWork = TRUE) {\n  # Logic below assumes a character string with non-missing values\n  # Note that an empty string is not a valid color, so parsing fails\n  # on NA input values, and thus, will be converted back to NA\n  # when `mustWork = FALSE`\n  isNA <- is.na(str)\n  if (!(is.character(str) || all(isNA))) {\n    stop(\"`str` must be a character vector (or NA).\")\n  }\n  str[isNA] <- \"\"\n\n  # Strip insignificant whitespace\n  str <- color_strip_ws(str)\n\n  strategies <- list(\n    # #RRGGBBAA and #RRGGBB\n    list(\n      pattern = \"^#([[:xdigit:]]{2})([[:xdigit:]]{2})([[:xdigit:]]{2})([[:xdigit:]]{2})?$\",\n      decoders = list(\n        decode_hex, # red\n        decode_hex, # green\n        decode_hex, # blue\n        decode_optional(decode_hex, 0xFF) # alpha, optional\n      ),\n      encoder = encode_hex\n    ),\n    # #RGBA and #RGB\n    list(\n      pattern = \"^#([[:xdigit:]])([[:xdigit:]])([[:xdigit:]])([[:xdigit:]])?$\",\n      decoders = list(\n        decode_hex, # red\n        decode_hex, # green\n        decode_hex, # blue\n        decode_optional(decode_hex, 0xFF) # alpha, optional\n      ),\n      encoder = encode_hex\n    ),\n    # rgb() and rgba()\n    list(\n      pattern = paste0(\"^rgba?\\\\(\",\n        \"(\", regex_float, \"),\",\n        \"(\", regex_float, \"),\",\n        \"(\", regex_float, \")\",\n        regex_non_capturing_group(\",(\", regex_float, \")\"), \"?\",\n        \"\\\\)$\"),\n      decoders = list(\n        decode_float_255, # red   [0-255]\n        decode_float_255, # green [0-255]\n        decode_float_255, # blue  [0-255]\n        decode_optional(decode_float_1, 0xFF) # alpha [0-1], optional\n      ),\n      encoder = encode_hex\n    ),\n    # hsl() and hsla()\n    list(\n      pattern = paste0(\"^hsla?\\\\(\",\n        \"(\", regex_float, \"),\",\n        \"(\", regex_float, \")%,\",\n        \"(\", regex_float, \")%\",\n        regex_non_capturing_group(\",(\", regex_float, \")\"), \"?\",\n        \"\\\\)$\"),\n      decoders = list(\n        decode_float_identity, # hue        [0-360]\n        decode_float_identity, # saturation [0-255]\n        decode_float_identity, # lightness  [0-255]\n        decode_optional(decode_float_1, 0xFF) # alpha [0-1], optional\n      ),\n      encoder = encode_hsl\n    ),\n    # color keywords\n    list(\n      pattern = paste0(\"^\", regex_color_keyword, \"$\"),\n      decoders = list(decode_color_keyword),\n      encoder = encode_hex\n    )\n  )\n\n  success <- rep_len(FALSE, length(str))\n  result <- rep_len(NA_character_, length(str))\n\n  for (strat in strategies) {\n    if (all(success)) {\n      break\n    }\n\n    res <- match_and_decode(\n      str[!success],\n      strat$pattern,\n      !!!strat$decoders\n    )\n    if (any(res$matching_rows)) {\n      result[!success][res$matching_rows] <- strat$encoder(res$values)\n      success[!success][res$matching_rows] <- TRUE\n    }\n  }\n\n  if (mustWork && any(!success)) {\n    stop(sprintf(\"CSS color value(s) could not be parsed: '%s'\", paste0(str[!success], collapse = \"', '\")))\n  }\n\n  result\n}"

const rtdal002605Source0003 = `match_and_decode <- function(str, pattern, ...) {
  # Example:
  # str <- c("#123456", "#ABCDEF")
  # pattern <- "#([0-9A-F]{2})([0-9A-F]{2})([0-9A-F]{2})"
  # args <- list(decode_hex, decode_hex, decode_hex)

  args <- rlang::list2(...)
  stopifnot(all(vapply(args, is.function, logical(1))))

  m <- regexec(pattern, str, ignore.case = TRUE)
  matching_rows <- vapply(m, function(x) { x[1] >= 0 }, logical(1)) # Ex: c(T,T)
  matches <- regmatches(str[matching_rows], m[matching_rows])
  if (length(matches) == 0) {
    return(list(
      matching_rows = matching_rows
    ))
  }

  col_count <- length(matches[[1]])
  str_matrix <- matrix(unlist(matches), ncol = col_count, byrow = TRUE)
  # Drop the first column, which is the entire matched string; we only want the
  # capturing groups
  str_matrix <- str_matrix[,-1,drop=FALSE]
  # Number of function arguments should match number of regex's capturing groups
  stopifnot(length(args) == ncol(str_matrix))
  # Ex: str_matrix
  #      [,1] [,2] [,3]
  # [1,] "12" "34" "56"
  # [2,] "AB" "CD" "EF"
  vals <- lapply(seq_len(ncol(str_matrix)), function(i) {
    # Ex: decode_hex(c("12", "AB")) => c(18, 171)
    args[[i]](str_matrix[,i])
  })
  results <- do.call(cbind, vals)
  # Ex: results
  #      [,1] [,2] [,3]
  # [1,]   18   52   86
  # [2,]  171  205  239

  return(list(
    matching_rows = matching_rows,
    values = results
  ))
}`

const rtdal002605Source0009 = `encode_hex <- function(values) {
  if (length(values) == 0) {
    return(character(0))
  }

  if (!is.matrix(values)) {
    stop("encode_hex requires a matrix argument")
  }
  if (ncol(values) < 3) {
    stop("encode_hex called with too few columns")
  }
  if (ncol(values) > 4) {
    stop("encode_hex called with too many columns")
  }
  if (!is.numeric(values)) {
    stop("encode_hex requires numeric values")
  }

  if (!is.integer(values)) {
    values <- round(values)
  }

  if (any(values > 255) || any(values < 0)) {
    stop("encode_hex values out of bounds")
  }

  red <- values[,1]
  green <- values[,2]
  blue <- values[,3]
  alpha <- if (ncol(values) > 3) {
    values[,4]
  } else {
    0xFF
  }
  colors <- ifelse(alpha == 0xFF,
    sprintf("#%02X%02X%02X", red, green, blue),
    sprintf("#%02X%02X%02X%02X", red, green, blue, alpha)
  )
  colors
}`

const rtdal002605Source0010 = `decode_color_keyword <- function(str) {
  color <- css_color_keywords[tolower(str)]
  if (anyNA(color)) {
    stop("Invalid color keyword(s)")
  }
  unname(t(grDevices::col2rgb(color, alpha = TRUE)))
}`

const rtdal002605Source0011 = `encode_hsl <- function(values) {
  if (length(values) == 0) {
    return(character(0))
  }

  if (!is.matrix(values)) {
    stop("encode_hsl requires a matrix argument")
  }
  if (ncol(values) < 3) {
    stop("encode_hsl called with too few columns")
  }
  if (ncol(values) > 4) {
    stop("encode_hsl called with too many columns")
  }
  if (!is.numeric(values)) {
    stop("encode_hsl requires numeric values")
  }

  # https://www.w3.org/TR/css-color-3/#hsl-color

  H <- values[,1]
  S <- values[,2] / 100
  L <- values[,3] / 100
  alpha <- if (ncol(values) > 3) {
    values[,4]
  } else {
    0xFF
  }

  # Clamp
  H <- (((H %% 360) + 360) %% 360) / 360
  S <- pmax(0, pmin(1, S))
  L <- pmax(0, pmin(1, L))

  hue_to_rgb <- function(m1, m2, h) {
    h <- ifelse(h < 0, h + 1,
      ifelse(h > 1, h - 1,
        h))
    ifelse(h * 6 < 1, m1+(m2-m1)*h*6,
      ifelse(h * 2 < 1, m2,
        ifelse(h * 3 < 2, m1+(m2-m1)*(2/3-h)*6,
          m1)))
  }

  M2 <- ifelse(L <= 0.5,
    L * (S + 1),
    L + S - L * S
  )
  M1 <- L * 2 - M2

  rgb <- cbind(
    hue_to_rgb(M1, M2, H+1/3),
    hue_to_rgb(M1, M2, H    ),
    hue_to_rgb(M1, M2, H-1/3)
  ) * 255
  rgb <- cbind(rgb, alpha)

  encode_hex(rgb)
}`

