const rtdal002615Source0001 = `envirMap <- function() {
  map <- fastmap()
  list(
    keys = map$keys,
    asList = function() {
      unname(map$as_list())
    },
    has = function(envir) {
      map$has(envir$envKey)
    },
    add = function(envir) {
      map$set(envir$envKey, TRUE)
    },
    remove = function(envir) {
      map$remove(envir$envKey)
    }
  )
}`

const rtdal002615Source0002 = `envirStack <- function() {
  stack <- faststack()
  list(
    push = stack$push,
    asList = stack$as_list,
    uniqueList = function() {
      unique(stack$as_list())
    }
  )
}`

const rtdal002615Source0003 = `envirStackUni_ <- function() {
  map <- fastmap()
  stack <- faststack()
  list(
    push = function(env) {
      key <- env$envKey
      if (!map$has(key)) {
        # mark the key as _seen_
        map$set(key, TRUE)
        # add the env
        stack$push(env)
      }
    },
    uniqueList = stack$as_list
  )
}`

const rtdal002615Source0004 = "envirStackUnique <- function() {\n  stack <- envirStack()\n  count <- 0\n  list(\n    push = function(env) {\n      count <<- count + 1\n      if (count == 500) {\n        # convert the current stack to a `envirStackUni_()`\n        newStack <- envirStackUni_()\n        walk(stack$asList(), newStack$push)\n        stack <<- newStack\n      }\n      stack$push(env)\n    },\n    uniqueList = function() {stack$uniqueList()}\n  )\n}"

const rtdal002615Source0005 = `copyAttributes <- function(from, to) {
  attrVals <- attributes(from)
  attrNames <- names(attrVals)
  for (i in seq_along(attrNames)) {
    attrName <- attrNames[i]
    switch(
      attrName,
      class = , comment =, dim =, dimnames =, names =, row.names =, tsp = NULL,
      {
        # Copy over the attribute
        attr(to, attrName) <- attrVals[[i]]
      }
    )
  }

  to
}`

const rtdal002615Source0006 = `safeListToEnv <- function(x, classToAdd = NULL) {
  xList <- x
  ret <- list2env(xList, new.env(parent = emptyenv()))
  ret <- copyAttributes(from = xList, to = ret)
  oldClass(ret) <- c(classToAdd, oldClass(xList))
  ret
}`

const rtdal002615Source0010 = "tagEnvToTags_ <- function(x) {\n  if (isTagEnv(x)) {\n\n    xEl <- x\n\n    # Pull the names `name`, `attribs`, and `children` first to match `tag()` name order\n    envNames <- ls(envir = xEl, all.names = TRUE, sorted = FALSE)\n    newNames <- c(\n      \"name\", \"attribs\", \"children\",\n      if (length(envNames) > 5) {\n        # Pull remaining names if they exist\n        removeFromSet(envNames, c(\"name\", \"attribs\", \"children\", \"parent\", \"envKey\"))\n      }\n    )\n\n    # Use mget to pull names in order to avoid always shuffling the values\n    x <- mget(newNames, xEl)\n    x <- copyAttributes(from = xEl, to = x)\n    oldClass(x) <- removeFromSet(oldClass(xEl), \"shiny.tag.env\")\n\n    # Recurse through children\n    children <- x$children\n    # Use a `for-loop` over `lapply` to avoid overhead\n    for (i in seq_along(children)) {\n      child <- children[[i]]\n      if (!is.null(child)) {\n        children[[i]] <- tagEnvToTags_(child)\n      }\n    }\n    x$children <- children\n  }\n  x\n}"

