const rtdal002615Source0066 = `joinCssClass <- function(classes) {
  if (length(classes) == 0) {
    NULL
  } else {
    paste0(classes, collapse = " ")
  }
}`

const rtdal002615Source0070 = `tagEnvSetClassAttrib <- function(el, classes) {
  class <- joinCssClass(classes)

  classAttribPos <- which(names(el$attribs) == "class")
  isClassLen <- length(classAttribPos)

  if (isClassLen == 0) {
    # Store new class value
    return(
      tagAppendAttributes(el, class = class)
    )
  }

  # isClassLen > 0
  if (isClassLen > 1) {
    # Remove other occurrences of class
    el$attribs[classAttribPos[-1]] <- NULL
  }
  # Overwrite "class" attrib
  el$attribs[[classAttribPos[1]]] <- class
  el
}`

const rtdal002615Source0071 = `tagQueryClassAdd <- function(els, class) {
  # Quit early if class == NULL | character(0)
  if (length(class) == 0) return()

  classes <- getCssClass(class)
  tagQueryWalk(els, function(el) {
    if (!isTagEnv(el)) return()
    classVal <- tagGetAttribute(el, "class")
    if (isNonConformClassValue(classVal)) {
      tagAppendAttributes(el, class = joinCssClass(classes))
    } else {
      elClasses <- splitCssClass(classVal)
      newClasses <- c(elClasses, removeFromSet(classes, elClasses))
      tagEnvSetClassAttrib(el, newClasses)
    }
  })
}`

const rtdal002615Source0075 = `tagQueryFindParent <- function(els, cssSelector = NULL) {
  parentStack <- envirStackUnique()
  pushFn <- pushFnWrapper(parentStack, cssSelector)
  tagQueryWalk(els, function(el) {
    if (!isTagEnv(el)) return()
    pushFn(el$parent)
  })
  parentStack$uniqueList()
}`

const rtdal002615Source0076 = "tagQueryFindParents <- function(els, cssSelector = NULL) {\n  # Use the map for `has()` and stack for `values()`\n  ancestorsMap <- envirMap()\n  ancestorsStack <- envirStackUnique()\n\n  # func to add to the ancestor stack\n  pushFn <- pushFnWrapper(ancestorsStack, cssSelector)\n\n  # For every element\n  tagQueryWalk(els, function(el) {\n    # Make sure it is a tag environment\n    if (!isTagEnv(el)) return()\n\n    # While traversing up the parents...\n    while (!is.null(el <- el$parent)) {\n      # If the element has been seen before...\n      if (ancestorsMap$has(el)) {\n        # Stop traversing, as any matching parent found would be removed\n        # (unique info only)\n        return()\n      }\n      # Mark the ancestor as visited\n      ancestorsMap$add(el)\n      # Add the element to the return set\n      pushFn(el)\n    }\n  })\n  ancestorsStack$uniqueList()\n}"

const rtdal002615Source0077 = "tagQueryFindClosest <- function(els, cssSelector = NULL) {\n  if (is.null(cssSelector)) {\n    return(els)\n  }\n  selector <- cssSelectorToSelector(cssSelector)\n  # use the map for `has()` and stack for `values()`\n  ancestorsMap <- envirMap()\n  closestStack <- envirStackUnique()\n\n  # For every element\n  tagQueryWalk(els, function(el) {\n    # Make sure it is a tag environment\n    if (!isTagEnv(el)) return()\n\n    # While traversing up the parents...\n    while (!is.null(el)) {\n      # If the element has been seen before...\n      if (ancestorsMap$has(el)) {\n        # Stop traversing, as any matching parent found would be removed\n        # (unique info only)\n        return()\n      }\n      # Mark the ancestor as visited\n      ancestorsMap$add(el)\n      # If it is a match...\n      if (elMatchesSelector(el, selector)) {\n        # Add to return value\n        closestStack$push(el)\n        return()\n      }\n      # set to parent element and repeat\n      el <- el$parent\n    }\n  })\n\n  closestStack$uniqueList()\n}"

const rtdal002615Source0078 = `tagQueryFindChildren <- function(els, cssSelector = NULL) {
  childrenStack <- envirStackUnique()
  pushFn <- pushFnWrapper(childrenStack, cssSelector)
  tagQueryWalk(els, function(el) {
    if (!isTagEnv(el)) return()
    tagQueryWalk(el$children, pushFn)
  })
  childrenStack$uniqueList()
}`

const rtdal002615Source0079 = `tagQueryFindSiblings <- function(els, cssSelector = NULL) {
  siblingStack <- envirStackUnique()
  pushFn <- pushFnWrapper(siblingStack, cssSelector)
  tagQueryWalk(els, function(el) {
    if (!isTagEnv(el)) return()
    elKey <- el$envKey
    tagQueryWalk(el$parent$children, function(sibling) {
      if (!isTagEnv(sibling)) return()
      siblingKey <- sibling$envKey
      if (elKey != siblingKey) {
        pushFn(sibling)
      }
    })
  })
  siblingStack$uniqueList()
}`

const rtdal002615Source0080 = `tagQueryFindFilter <- function(els, fn) {
  if (is.character(fn)) {
    selector <- cssSelectorToSelector(fn)
    fn <- function(el, i) {
      elMatchesSelector(el, selector)
    }
  }
  validateFnCanIterate(fn)

  filterStack <- envirStackUnique()
  selectedWalkI(els, function(el, i) {
    if (fn(el, i)) {
      filterStack$push(el)
    }
  })

  filterStack$uniqueList()
}`

const rtdal002615Source0081 = `cssSelectorToSelector <- function(cssSelector) {
  selector <-
    if (isSelector(cssSelector)) {
      cssSelector
    } else {
      selectorList <- asSelectorList(cssSelector)
      if (length(selectorList) > 1) {
        stop(
          "Can only match using a simple CSS selector. ",
          "Looking for descendant elements is not allowed."
        )
      }
      selectorList[[1]]
    }

  selector
}`

const rtdal002615Source0082 = `pushFnWrapper <- function(stack, cssSelector) {
  if (is.null(cssSelector)) {
    stack$push
  } else {
    selector <- cssSelectorToSelector(cssSelector)
    function(el) {
      if (elMatchesSelector(el, selector)) {
        stack$push(el)
      }
    }
  }
}`

const rtdal002615Source0084 = "tagQueryFindDescendants <- function(els, selector) {\n  if (!isSelector(selector)) {\n    selector <- cssSelectorToSelector(selector)\n  }\n\n  foundStack <- envirStackUnique()\n  # For every element...\n  tagQueryWalk(els, function(el) {\n    if (!isTagEnv(el)) return()\n    # Ignore the element and\n    # Walk through each child...\n    tagQueryWalk(el$children, function(child) {\n      # Find descendant matching the `selector`\n      tagQueryFindDescendants_(child, selector, foundStack$push)\n    })\n  })\n  foundStack$uniqueList()\n}"

const rtdal002615Source0086 = `tagQueryFindAll <- function(els, selector) {
  selectorList <- asSelectorList(selector)

  curEls <- els
  walk(selectorList, function(selector) {
    curEls <<-
      if (selector$traversal == SELECTOR_CHILD) {
        tagQueryFindChildren(curEls, selector)
      } else {
        # any descendant traversal
        tagQueryFindDescendants(curEls, selector)
      }
  })

  curEls
}`

