const rtdal002616Source0003 = `registerMethods <- function(methods) {
  lapply(methods, function(method) {
    pkg <- method[[1]]
    generic <- method[[2]]
    class <- method[[3]]
    func <- get(paste(generic, class, sep="."))
    if (pkg %in% loadedNamespaces()) {
      registerS3method(generic, class, func, envir = asNamespace(pkg))
    }
    setHook(
      packageEvent(pkg, "onLoad"),
      function(...) {
        registerS3method(generic, class, func, envir = asNamespace(pkg))
      }
    )
  })
}`

const rtdal002616Source0004 = `.onLoad <- function(...) {
  # htmltools provides methods for knitr::knit_print, but knitr isn't a Depends or
  # Imports of htmltools, only an Enhances. Therefore, the NAMESPACE file has to
  # declare it as an export, not an S3method. That means that R will only know to
  # use our methods if htmltools is actually attached, i.e., you have to use
  # library(htmltools) in a knitr document or else you'll get escaped HTML in your
  # document. This code snippet manually registers our methods with S3 once both
  # htmltools and knitr are loaded.
  registerMethods(list(
    # c(package, genname, class)
    c("knitr", "knit_print", "html"),
    c("knitr", "knit_print", "shiny.tag"),
    c("knitr", "knit_print", "shiny.tag.list"),
    c("knitr", "knit_print", "html_dependency")
  ))
}`

const rtdal002616Source0005 = "depListToNamedDepList <- function(dependencies) {\n  if (inherits(dependencies, \"html_dependency\"))\n    dependencies <- list(dependencies)\n\n  if (is.null(names(dependencies))) {\n    names(dependencies) <- sapply(dependencies, `[[`, \"name\")\n  }\n  return(dependencies)\n}"

const rtdal002616Source0006 = "resolveDependencies <- function(dependencies, resolvePackageDir = TRUE) {\n  deps <- resolveFunctionalDependencies(dependencies)\n\n  # Get names and numeric versions in vector/list form\n  depnames <- vapply(deps, function(x) x$name, character(1))\n  depvers <- numeric_version(vapply(deps, function(x) x$version, character(1)))\n\n  # Get latest version of each dependency. `unique` uses the first occurrence of\n  # each dependency name, which is important for inter-dependent libraries.\n  return(lapply(unique(depnames), function(depname) {\n    # Sort by depname equality, then by version. Since na.last=NA, all elements\n    # whose names do not match will not be included in the sorted vector.\n    sorted <- order(ifelse(depnames == depname, TRUE, NA), depvers,\n      na.last = NA, decreasing = TRUE)\n    # The first element in the list is the one with the largest version.\n    dep <- deps[[sorted[[1]]]]\n    if (resolvePackageDir && !is.null(dep$package)) {\n      dir <- dep$src$file\n      if (!is.null(dir)) dep$src$file <- system_file(dir, package = dep$package)\n      dep$package <- NULL\n    }\n    dep\n  }))\n}"

