const rtdal002628Source0027 = "test_that(\"tagQuery() allows for tags with extra top level items and will preserve them\", {\n  html <- div(span())\n  html$test <- \"extra\"\n  html <- c(list(first = TRUE), html)\n  class(html) <- \"shiny.tag\"\n\n  # Test different removal types: setting the value to NULL and removing the value from the envir completely.\n  for (removeType in c(\"set\", \"rm\")) {\n    expect_error(\n      tagQuery(html)$each(function(el, i) {\n        switch(removeType,\n          set = {\n            el$name <- NULL\n          },\n          rm = {\n            rm(list = \"name\", envir = el)\n          }\n        )\n      })$allTags(),\n      \"lost its `$name`\", fixed = TRUE\n    )\n\n    for (missing_key in c(\"__not_a_match__\", \"attribs\", \"children\")) {\n      htmlQ <- tagQuery(html)\n      if (missing_key %in% names(html)) {\n        htmlQ$each(function(el, i) {\n          switch(removeType,\n            set = {\n              el[[missing_key]] <- NULL\n            },\n            rm = {\n              rm(list = missing_key, envir = el)\n            }\n          )\n          el[[missing_key]] <- NULL\n        })\n      }\n      htmlPostQ <- htmlQ$allTags()\n      html_out <- html\n      if (missing_key == \"attribs\") html_out$attribs <- dots_list()\n      if (missing_key == \"children\") html_out$children <- list()\n      # expect first three names to be standard tag names\n      expect_equal(names(htmlPostQ)[1:3], names(div()))\n\n      # expect all other names to be included somewhere\n      expect_setequal(names(htmlPostQ), names(html_out))\n\n      # If done in the same order, it should be equal\n      back_to_orig <- htmlPostQ[names(html_out)]\n      class(back_to_orig) <- \"shiny.tag\"\n      expect_equal(back_to_orig, html_out)\n    }\n  }\n\n})"

const rtdal002628Source0028 = `test_that("tag methods do not unexpectedly alter tag envs", {

  expect_equal_tags(
    tagEnvToTags(tagAppendAttributes(asTagEnv(div()), key = "a")),
    tagAppendAttributes(div(), key = "a")
  )

  expect_equal_tags(
    tagHasAttribute(asTagEnv(div(key = "a")), "key"),
    tagHasAttribute(div(key = "a"), "key")
  )

  expect_equal_tags(
    tagGetAttribute(asTagEnv(div(key = "a")), "key"),
    tagGetAttribute(div(key = "a"), "key")
  )

  expect_equal_tags(
    tagEnvToTags(tagAppendChild(asTagEnv(div()), span())),
    tagAppendChild(div(), span())
  )

  expect_equal_tags(
    tagEnvToTags(tagAppendChildren(asTagEnv(div()), span(), h1())),
    tagAppendChildren(div(), span(), h1())
  )

  expect_equal_tags(
    tagEnvToTags(tagSetChildren(asTagEnv(div()), span(), h1())),
    tagSetChildren(div(), span(), h1())
  )

  expect_equal_tags(
    tagEnvToTags(tagInsertChildren(asTagEnv(div()), span(), h1(), after = 12)),
    tagInsertChildren(div(), span(), h1(), after = 12)
  )
})`

const rtdal002628Source0029 = `test_that("adding a class does not reorder attribs", {

  # No class
  expect_equal_tags(
    tagQuery(div(test = "A", "text"))$addClass("foo")$allTags(),
    div(test = "A", class = "foo", "text")
  )

  # One class
  expect_equal_tags(
    tagQuery(div(class = "bar", test = "A", "text"))$addClass("foo")$allTags(),
    div(class="bar foo", test = "A", "text")
  )

  # Multiple classes
  expect_equal_tags(
    tagQuery(div(class = "bar", test = "A", class = "baz", "text"))$addClass("foo")$allTags(),
    div(class = "bar baz foo", test = "A", "text")
  )
})`

const rtdal002628Source0030 = "test_that(\"flattenTagsRaw() and flattenTags() do not drop html deps\", {\n  emptyDiv <- div()\n  emptySpan <- span()\n  testSpan <- span(\"test\")\n  otherObj <- HTML(\"test\")\n\n  fakeDep <- function(i) {\n    ret <- fakeJqueryDep\n    ret$i <- i\n    ret\n  }\n\n  # `flattenTagsRaw()` moves html deps on tag lists to children\n  htmlRaw <- tagList(\n    emptyDiv,\n    tagAppendChild(emptySpan, fakeDep(1)),\n    tagAppendChild(testSpan, fakeDep(2)),\n    otherObj,\n    fakeDep(3)\n  )\n\n  htmlDependencies(emptySpan) <- list(fakeDep(1))\n  htmlDependencies(testSpan) <- list(fakeDep(2))\n  html <- tagList(\n    emptyDiv,\n    emptySpan,\n    testSpan,\n    otherObj\n  )\n  htmlDependencies(html) <- list(fakeDep(3))\n\n  expect_equal(flattenTags(html), html)\n  expect_equal(flattenTagsRaw(html), htmlRaw)\n})"

const rtdal002628Source0031 = `test_that("flattenTagsRaw(): tag list html deps are not lost when tag children are squashed", {
  # https://github.com/rstudio/htmltools/issues/301

  a_dep <- htmlDependency(name = "A", version = 1, src = "a.js")
  b_dep <- htmlDependency(name = "B", version = 2, src = "b.js")
  c_dep <- htmlDependency(name = "C", version = 3, src = "c.js")
  d_dep <- htmlDependency(name = "D", version = 4, src = "d.js")

  z <- div("Z")
  z$children <- list(attachDependencies(list("z1"), d_dep))

  children <-
    attachDependencies(
      list(
        attachDependencies(list("X", "Y"), a_dep),
        z
      ),
      list(b_dep, c_dep)
    )

  html <- div("test", children)
  tq_html <- tagQuery(html)$allTags()

  tq_deps <- findDependencies(tq_html$children)
  expect_length(tq_deps, 4)
  expect_equal(tq_deps, list(a_dep, d_dep, b_dep, c_dep))
})`

