const rtdal002629Source0002 = `test_that("Basic tag writing works", {
  expect_equal(as.character(tagList("hi")), "hi")
  expect_equal(
    as.character(tagList("one", "two", tagList("three"))),
    "one\ntwo\nthree")
  expect_equal(
    as.character(tags$b("one")),
    "<b>one</b>")
  expect_equal(
    as.character(tags$b("one", "two")),
    "<b>\n  one\n  two\n</b>")
  expect_equal(
    as.character(tagList(list("one"))),
    "one")
  expect_equal(
    as.character(tagList(list(tagList("one")))),
    "one")
  expect_equal(
    as.character(tagList(tags$br(), "one")),
    "<br/>\none")
})`

const rtdal002629Source0003 = `test_that("Hanging commas don't break things", {
  expect_equal(as.character(tagList("hi",)), "hi")
  expect_equal(as.character(div("one",)), "<div>one</div>")
  # Multiple commas still throw
  err_comma_multiple <- expect_error(as.character(div("one",,)))
  # Non-trailing commas still throw
  err_comma_leading <- expect_error(as.character(div(,"one",)))

  # rlang > 1.0.6 changed the error message, so only run
  # snapshot testing of the error message with the new version
  skip_if_not_installed("rlang", "1.0.6.9000")
  local_edition(3)
  expect_snapshot(err_comma_multiple)
  expect_snapshot(err_comma_leading)
})`

const rtdal002629Source0004 = `test_that("withTags works", {
  output_tags <- tags$div(class = "myclass",
    tags$h3("header"),
    tags$p("text here")
  )
  output_withhtml <- withTags(
    div(class = "myclass",
      h3("header"),
      p("text here")
    )
  )
  expect_identical(output_tags, output_withhtml)


  # Check that current environment is searched
  x <- 100
  expect_identical(tags$p(x), withTags(p(x)))

  # Just to make sure, run it in a function, which has its own environment
  foo <- function() {
    y <- 100
    withTags(p(y))
  }
  expect_identical(tags$p(100), foo())
})`

const rtdal002629Source0005 = `test_that(".noWS argument of withTags()", {
  get_noWS <- function(tag) tag[[".noWS"]]

  default <- withTags(
    div(
      class = "myclass",
      h3("header"),
      p("One", strong(span("two")), "three")
    )
  )

  expect_null(get_noWS(default))
  expect_null(get_noWS(default$children[[1]]))
  expect_null(get_noWS(default$children[[2]]))
  expect_null(get_noWS(default$children[[2]]$children[[2]]))
  expect_null(get_noWS(default$children[[2]]$children[[2]]$children[[1]]))

  default_special <- withTags(
    div(
      class = "myclass",
      h3("header", .noWS = "after-begin"),
      p("One", strong(span("two")), "three", .noWS = "before-end")
    )
  )

  expect_null(get_noWS(default_special))
  expect_equal(get_noWS(default_special$children[[1]]), "after-begin")
  expect_equal(get_noWS(default_special$children[[2]]), "before-end")
  expect_null(get_noWS(default_special$children[[2]]$children[[2]]))
  expect_null(get_noWS(default_special$children[[2]]$children[[2]]$children[[1]]))

  all_same_noWS <- c("outside", "inside")
  all_same <- withTags(
    div(
      class = "myclass",
      h3("header"),
      p("One", strong(span("two")), "three")
    ),
    .noWS = all_same_noWS
  )

  expect_equal(get_noWS(all_same), all_same_noWS)
  expect_equal(get_noWS(all_same$children[[1]]), all_same_noWS)
  expect_equal(get_noWS(all_same$children[[2]]), all_same_noWS)
  expect_equal(get_noWS(all_same$children[[2]]$children[[2]]), all_same_noWS)
  expect_equal(get_noWS(all_same$children[[2]]$children[[2]]$children[[1]]), all_same_noWS)

  varied_default <- "outside"
  varied_special <- "inside"
  varied <- withTags(
    div(
      class = "myclass",
      h3("header"),
      p("One", strong(span("two"), .noWS = varied_special), "three")
    ),
    .noWS = varied_default
  )

  expect_equal(get_noWS(varied), varied_default)
  expect_equal(get_noWS(varied$children[[1]]), varied_default)
  expect_equal(get_noWS(varied$children[[2]]), varied_default)
  expect_equal(get_noWS(varied$children[[2]]$children[[2]]), varied_special)
  expect_equal(get_noWS(varied$children[[2]]$children[[2]]$children[[1]]), varied_default)
})`

const rtdal002629Source0006 = `test_that("HTML escaping in tags", {
  # Regular text is escaped
  expect_equivalent(format(div("<a&b>")), "<div>&lt;a&amp;b&gt;</div>")

  # Text in HTML() isn't escaped
  expect_equivalent(format(div(HTML("<a&b>"))), "<div><a&b></div>")

  # Text in a property is escaped
  expect_equivalent(format(div(class = "<a&b>", "text")),
    '<div class="&lt;a&amp;b&gt;">text</div>')

  # HTML() has no effect in a property like 'class'
  expect_equivalent(format(div(class = HTML("<a&b>"), "text")),
    '<div class="&lt;a&amp;b&gt;">text</div>')
})`

const rtdal002629Source0007 = "test_that(\"Adding child tags\", {\n  tag_list <- list(tags$p(\"tag1\"), tags$b(\"tag2\"), tags$i(\"tag3\"))\n\n  # Creating nested tags by calling the tag$div function and passing a list\n  t1 <- tags$div(class=\"foo\", tag_list)\n  expect_equal(length(t1$children), 1)\n  expect_equal(length(t1$children[[1]]), 3)\n  expect_equal(t1$children[[1]][[1]]$name, \"p\")\n  expect_equal(t1$children[[1]][[1]]$children[[1]], \"tag1\")\n  expect_equal(t1$children[[1]][[2]]$name, \"b\")\n  expect_equal(t1$children[[1]][[2]]$children[[1]], \"tag2\")\n  expect_equal(t1$children[[1]][[3]]$name, \"i\")\n  expect_equal(t1$children[[1]][[3]]$children[[1]], \"tag3\")\n\n\n  # div tag used as starting point for tests below\n  div_tag <- tags$div(class=\"foo\")\n\n  # Appending each child\n  t2 <- tagAppendChild(div_tag, tag_list[[1]])\n  t2 <- tagAppendChild(t2, tag_list[[2]])\n  t2 <- tagAppendChild(t2, tag_list[[3]])\n  t2a <- do.call(tags$div, c(tag_list, class=\"foo\"))\n  expect_identical(t2a, t2)\n  t2b <- tagAppendChildren(div_tag, `names_are_ignored` = tag_list[[1]],\n    \"ignore-this-name\" = tag_list[[2]],\n    dummyName = tag_list[[3]])\n  expect_identical(t2b, t2)\n\n  # tagSetChildren, using list argument\n  t2 <- tagSetChildren(div_tag, list = tag_list)\n  expect_identical(t2a, t2)\n\n  # tagSetChildren, using ... arguments\n  t2 <- tagSetChildren(div_tag, tag_list[[1]], tag_list[[2]], tag_list[[3]])\n  expect_identical(t2a, t2)\n\n  # tagSetChildren, using named ... arguments (names should be ignored)\n  t2 <- tagSetChildren(div_tag, ignored = tag_list[[1]], dummy = tag_list[[2]], blah = tag_list[[3]])\n  expect_identical(t2a, t2)\n\n  # tagSetChildren, using ... and list arguments\n  t2 <- tagSetChildren(div_tag, tag_list[[1]], list = tag_list[2:3])\n  expect_identical(t2a, t2)\n\n  # tagSetChildren overwrites existing children\n  t2 <- tagAppendChild(div_tag, p(\"should replace this tag\"))\n  t2 <- tagSetChildren(div_tag, list = tag_list)\n  expect_identical(t2a, t2)\n\n\n  # tagAppendChildren, using list argument\n  t2 <- tagAppendChild(div_tag, tag_list[[1]])\n  t2 <- tagAppendChildren(t2, list = tag_list[2:3])\n  expect_identical(t2a, t2)\n\n  # tagAppendChildren, using ... arguments\n  t2 <- tagAppendChild(div_tag, tag_list[[1]])\n  t2 <- tagAppendChildren(t2, tag_list[[2]], tag_list[[3]])\n  expect_identical(t2a, t2)\n\n  # tagAppendChildren, using ... and list arguments\n  t2 <- tagAppendChild(div_tag, tag_list[[1]])\n  t2 <- tagAppendChildren(t2, tag_list[[2]], list = list(tag_list[[3]]))\n  expect_identical(t2a, t2)\n\n  # tagAppendChildren can start with no children\n  t2 <- tagAppendChildren(div_tag, list = tag_list)\n  expect_identical(t2a, t2)\n\n\n  # tagSetChildren preserves attributes\n  x <- tagSetChildren(div(), HTML(\"text\"))\n  expect_identical(attr(x$children[[1]], \"html\", TRUE), TRUE)\n\n  # tagAppendChildren preserves attributes\n  x <- tagAppendChildren(div(), HTML(\"text\"))\n  expect_identical(attr(x$children[[1]], \"html\", TRUE), TRUE)\n})"

const rtdal002629Source0008 = `test_that("Creating simple tags", {
  # Empty tag
  expect_identical(
    div(),
    structure(
      list(name = "div", attribs = dots_list(), children = list()),
      .Names = c("name", "attribs", "children"),
      class = "shiny.tag"
    )
  )

  # Tag with text
  expect_identical(
    div("text"),
    structure(
      list(name = "div", attribs = dots_list(), children = list("text")),
      .Names = c("name", "attribs", "children"),
      class = "shiny.tag"
    )
  )

  # NULL attributes are dropped
  expect_identical(
    div(a = NULL, b = "value"),
    div(b = "value")
  )

  # length-0 attributes are dropped
  expect_identical(
    div(a = character(), b = "value"),
    div(b = "value")
  )

  # NULL children are dropped
  expect_identical(
    renderTags(div("foo", NULL, list(NULL, list(NULL, "bar"))))$html,
    renderTags(div("foo", "bar"))$html
  )

  # length-0 children are dropped
  expect_identical(
    renderTags(div("foo", character(), list(character(), list(list(), "bar"))))$html,
    renderTags(div("foo", "bar"))$html
  )

  # Numbers are coerced to strings
  expect_identical(
    renderTags(div(1234))$html,
    renderTags(div("1234"))$html
  )
})`

const rtdal002629Source0009 = `test_that("Creating nested tags", {
  # Simple version
  # Note that the $children list should not have a names attribute
  expect_identical(
    div(class="foo", list("a", "b")),
    structure(
      list(name = "div",
        attribs = structure(list(class = "foo"), .Names = "class"),
        children = list(list("a", "b"))),
      .Names = c("name", "attribs", "children"),
      class = "shiny.tag"
    )
  )

  # More complex version
  t1 <- withTags(
    div(class = "foo",
      p("child tag"),
      list(
        p("in-list child tag 1"),
        "in-list character string",
        p(),
        p("in-list child tag 2")
      ),
      "character string",
      1234
    )
  )

  # t1 should be identical to this data structure.
  # The nested list should be flattened, and non-tag, non-strings should be
  # converted to strings
  t1_full <- structure(
    list(
      name = "div",
      attribs = list(class = "foo"),
      children = list(
        structure(list(name = "p",
          attribs = list(),
          children = list("child tag")),
          class = "shiny.tag"
        ),
        structure(list(name = "p",
          attribs = list(),
          children = list("in-list child tag 1")),
          class = "shiny.tag"
        ),
        "in-list character string",
        structure(list(name = "p",
          attribs = list(),
          children = list()),
          class = "shiny.tag"
        ),
        structure(list(name = "p",
          attribs = list(),
          children = list("in-list child tag 2")),
          class = "shiny.tag"
        ),
        "character string",
        "1234"
      )
    ),
    class = "shiny.tag"
  )

  expect_identical(renderTags(t1)$html, renderTags(t1_full)$html)
})`

