const rtdal002636Source0021 = "widget_data <- function(x, id, ...){\n  # It's illegal for </script> to appear inside of a script tag, even if it's\n  # inside a quoted string. Fortunately we know that in JSON, the only place\n  # the '<' character can appear is inside a quoted string, where a Unicode\n  # escape has the same effect, without confusing the browser's parser. The\n  # repro for the bug this gsub fixes is to have the string \"</script>\" appear\n  # anywhere in the data/metadata of a widget--you will get a syntax error\n  # instead of a properly rendered widget.\n  #\n  # Another issue is that if </body></html> appears inside a quoted string,\n  # then when pandoc coverts it with --self-contained, the escaping gets messed\n  # up. There may be other patterns that trigger this behavior, so to be safe\n  # we can replace all instances of \"</\" with \"\\\\u003c/\".\n  payload <- toJSON(createPayload(x))\n  payload <- gsub(\"</\", \"\\\\u003c/\", payload, fixed = TRUE)\n  tags$script(type = \"application/json\", `data-for` = id, HTML(payload))\n}"

const rtdal002636Source0022 = `createWidget <- function(name,
                         x,
                         width = NULL,
                         height = NULL,
                         sizingPolicy = htmlwidgets::sizingPolicy(),
                         package = name,
                         dependencies = NULL,
                         elementId = NULL,
                         preRenderHook = NULL) {
  # Turn single dependency object into list of dependencies, if necessary
  if (inherits(dependencies, "html_dependency"))
    dependencies <- list(dependencies)
  structure(
    list(x = x,
         width = width,
         height = height,
         sizingPolicy = sizingPolicy,
         dependencies = dependencies,
         elementId = elementId,
         preRenderHook = preRenderHook,
         jsHooks = list()),
    class = c(name,
              if (sizingPolicy$viewer$suppress) "suppress_viewer",
              "htmlwidget"),
    package = package
  )
}`

const rtdal002636Source0023 = "shinyWidgetOutput <- function(outputId, name, width, height, package = name,\n                              inline = FALSE, reportSize = TRUE, reportTheme = FALSE,\n                              fill = !inline) {\n\n  # Theme reporting requires this shiny feature\n  # https://github.com/rstudio/shiny/pull/2740/files\n  if (reportTheme && !is_installed(\"shiny\", \"1.4.0.9003\")) {\n    message(\"`reportTheme = TRUE` requires shiny v.1.4.0.9003 or higher. Consider upgrading shiny.\")\n  }\n\n  tag <- widget_html(\n    name, package, id = outputId,\n    class = paste0(\n      name, \" html-widget html-widget-output\",\n      if (reportSize) \" shiny-report-size\",\n      if (reportTheme) \" shiny-report-theme\"\n    ),\n    style = css(\n      width = validateCssUnit(width),\n      height = validateCssUnit(height),\n      display = if (inline) \"inline-block\"\n    ),\n    width = width,\n    height = height\n  )\n\n  tag <- bindFillRole(tag, item = fill)\n\n  # Adds an additional and unnecessary tagList() container to the return value...\n  # I'd love remove it, but lets keep it for backwards-compatibility\n  tag <- tagList(tag)\n\n  attachDependencies(\n    tag, widget_dependencies(name, package), append = TRUE\n  )\n}"

const rtdal002636Source0024 = `shinyRenderWidget <- function(expr, outputFunction, env, quoted, cacheHint = "auto")  {
  # generate a function for the expression
  shiny::installExprFunction(expr, "func", env, quoted)

  renderWidget <- function(instance) {
    if (!is.null(instance$elementId)) {
      warning("Ignoring explicitly provided widget ID \"",
        instance$elementId, "\"; Shiny doesn't use them"
      )
    }

    # We don't support prependContent/appendContent in dynamic Shiny contexts
    # because the Shiny equivalent of onStaticRenderComplete is unclear. If we
    # ever figure that out it would be great to support it. One possibility
    # would be to have a dedicated property for "post-render customization JS",
    # I suppose. In any case, it's less of a big deal for Shiny since there are
    # other mechanisms (that are at least as natural) for putting custom JS in a
    # Shiny app.
    if (!is.null(instance$prepend)) {
      warning("Ignoring prepended content; prependContent can't be used in a ",
        "Shiny render call")
    }
    if (!is.null(instance$append)) {
      warning("Ignoring appended content; appendContent can't be used in a ",
        "Shiny render call")
    }

    deps <- .subset2(instance, "dependencies")
    deps_payload <- lapply(
      htmltools::resolveDependencies(deps),
      shiny::createWebDependency
    )
    payload <- c(createPayload(instance), list(deps = deps_payload))
    payload <- toJSON(payload)
    attr(payload, "deps") <- deps
    payload
  }

  # The cacheHint and cacheReadHook args were added in Shiny 1.6.0.
  if (all(c("cacheHint", "cacheReadHook") %in% names(formals(shiny::createRenderFunction)))) {
    shiny::createRenderFunction(
      func,
      function(instance, session, name, ...) {
        renderWidget(instance)
      },
      outputFunction,
      NULL,
      cacheHint = cacheHint,
      cacheReadHook = function(value) {
        # If we've pulled the value from the cache and we're in a different R
        # process from the one that created it, we'll need to register the
        # dependencies again.
        deps <- attr(value, "deps")
        lapply(
          htmltools::resolveDependencies(deps),
          shiny::createWebDependency
        )
        value
      }
    )
  } else {
    shiny::createRenderFunction(
      func,
      function(instance, session, name, ...) {
        renderWidget(instance)
      },
      outputFunction,
      NULL
    )
  }

}`

