const rtdal002644Source0001 = `toJSON2 <- function(
  x, ...,  dataframe = "columns", null = "null", na = "null", auto_unbox = TRUE,
  digits = getOption("shiny.json.digits", 16), use_signif = TRUE, force = TRUE,
  POSIXt = "ISO8601", UTC = TRUE, rownames = FALSE, keep_vec_names = TRUE,
  strict_atomic = TRUE
) {
  if (strict_atomic) x <- I(x)
  jsonlite::toJSON(
    x, dataframe = dataframe, null = null, na = na, auto_unbox = auto_unbox,
    digits = digits, use_signif = use_signif, force = force, POSIXt = POSIXt,
    UTC = UTC, rownames = rownames, keep_vec_names = keep_vec_names,
    json_verbatim = TRUE, ...
  )
}`

const rtdal002644Source0002 = `toJSON <- function(x) {
  if (!is.list(x) || !('x' %in% names(x))) return(toJSON2(x))
  func <- attr(x$x, 'TOJSON_FUNC', exact = TRUE)
  args <- attr(x$x, 'TOJSON_ARGS', exact = TRUE)
  if (length(args) == 0) args <- getOption('htmlwidgets.TOJSON_ARGS')
  if (!is.function(func)) func <- toJSON2
  res <- if (length(args) == 0) func(x) else do.call(func, c(list(x = x), args))
  # make sure shiny:::toJSON() does not encode it again
  structure(res, class = 'json')
}`

const rtdal002644Source0003 = "getDependency <- function(name, package = name){\n  config = sprintf(\"htmlwidgets/%s.yaml\", name)\n  jsfile = sprintf(\"htmlwidgets/%s.js\", name)\n\n  # if yaml does not exist then assume no dependencies\n  #  in this cases dependencies should be provided through the\n  #  dependencies argument of createWidget\n  widgetDep <- list()\n  yaml_file <- system_file(config, package = package)\n  if (file.exists(yaml_file)) {\n    config = yaml::yaml.load_file(yaml_file)\n    widgetDep <- lapply(config$dependencies, function(l) {\n      l$package = package\n      do.call(htmlDependency, l)\n    })\n  }\n\n  # if js binding does not exist then assume provided through\n  #  some other mechanism such as a specified `htmlDependency` or `script` tag.\n  #  Note, this is a very special case.\n  bindingDep <- if (file.exists(system_file(jsfile, package = package))) {\n    htmlDependency(\n      name = paste0(name, \"-binding\"),\n      version = get_package_version(package),\n      src = \"htmlwidgets\",\n      package = package,\n      script = basename(jsfile),\n      all_files = FALSE\n    )\n  }\n\n  c(\n    list(htmlDependency(\n      name = \"htmlwidgets\",\n      version = get_package_version(\"htmlwidgets\"),\n      src = \"www\",\n      package = \"htmlwidgets\",\n      script = \"htmlwidgets.js\"\n    )),\n    widgetDep,\n    list(bindingDep)\n  )\n}"

const rtdal002644Source0004 = `prop <- function(x, path) {
  tryCatch({
    for (i in strsplit(path, "$", fixed = TRUE)[[1]]) {
      if (is.null(x))
        return(NULL)
      x <- x[[i]]
    }
    return(x)
  }, error = function(e) {
    return(NULL)
  })
}`

const rtdal002644Source0006 = `JS <- function(...) {
  x <- c(...)
  if (is.null(x)) return()
  if (!is.character(x))
    stop("The arguments for JS() must be a character vector")
  x <- paste(x, collapse = '\n')
  structure(x, class = unique(c("JS_EVAL", oldClass(x))))
}`

const rtdal002644Source0008 = `shouldEval <- function(options) {
  if (is.list(options)) {
    if (inherits(options, "POSIXlt")) return(FALSE)
    if ((n <- length(options)) == 0) return(FALSE)
    # use numeric indices as names (remember JS indexes from 0, hence -1 here)
    if (is.null(names(options)))
      names(options) <- as.character(seq_len(n) - 1L)
    # Escape '\' and '.' by prefixing them with '\'. This allows us to tell the
    # difference between periods as separators and periods that are part of the
    # name itself.
    names(options) <- gsub("([\\.])", "\\\\\\1", names(options))
    nms <- names(options)
    if (length(nms) != n || any(nms == ''))
      stop("'options' must be a fully named list, or have no names (NULL)")
    lapply(options, shouldEval)
  } else {
    is.character(options) && inherits(options, 'JS_EVAL')
  }
}`

const rtdal002644Source0009 = `onStaticRenderComplete <- function(jsCode) {
  tags$script(
    "HTMLWidgets.addPostRenderHandler(function() {",
    HTML(paste0(jsCode, collapse = "\n")),
    "});"
  )
}`

