const rtdal002661Source0002 = `curl_fetch_async <- function(
  url,
  pool = NULL,
  data = NULL,
  handle = curl::new_handle()
) {
  p <- promises::promise(function(resolve, reject) {
    curl::curl_fetch_multi(
      url,
      done = resolve,
      fail = reject,
      pool = pool,
      data = data,
      handle = handle
    )
  })

  finished <- FALSE
  poll <- function() {
    if (!finished) {
      curl::multi_run(timeout = 0, poll = TRUE, pool = pool)
      later::later(poll, 0.01)
    }
  }
  poll()

  p %>%
    finally(function() {
      finished <<- TRUE
    })
}`

const rtdal002661Source0003 = `http_request_con_async <- function(request, host, port) {
  resolve_fun <- NULL
  reject_fun <- NULL
  con <- NULL

  p <- promises::promise(function(resolve, reject) {
    resolve_fun <<- resolve
    reject_fun <<- reject
    con <<- socketConnection(host, port)
    writeLines(c(request, ""), con)
  })

  result <- NULL
  # finished <- FALSE
  poll <- function() {
    result <<- readLines(con)
    if (length(result) > 0) {
      resolve_fun(result)
    } else {
      later::later(poll, 0.01)
    }
  }
  poll()

  p %>%
    finally(function() {
      close(con)
    })
}`

const rtdal002661Source0004 = `wait_for_it <- function() {
  while (!later::loop_empty()) {
    later::run_now()
  }
}`

const rtdal002661Source0005 = `extract <- function(promise) {
  promise_value <- NULL
  error <- NULL
  promise %...>%
    (function(value) promise_value <<- value) %...!%
    (function(reason) error <<- reason)

  wait_for_it()
  if (!is.null(error)) {
    stop(error)
  } else {
    promise_value
  }
}`

const rtdal002661Source0006 = `fetch <- function(url, handle = curl::new_handle(), gzip = TRUE) {
  if (!gzip) {
    # Disable gzip; this is often needed only because the unit tests predate
    # gzip support in httpuv
    curl::handle_setopt(handle, accept_encoding = NULL)
  }

  p <- curl_fetch_async(url, handle = handle)
  extract(p)
}`

