const rtdal002667Source0004 = `path_example_site <- function(...) {
  system.file("example-static-site", ..., package = "httpuv")
}`

const rtdal002667Source0008 = `start_example_server <- function(port) {
  r <- callr::r_bg(
    function(port) {
      ex <- system.file("example-static-site", package = "httpuv")
      httpuv::runStaticServer(
        ex,
        port = port,
        background = FALSE,
        browse = FALSE
      )
    },
    list(port = port)
  )

  max <- Sys.time() + 2
  while (length(r$read_error_lines()) == 0) {
    if (Sys.time() > max) {
      skip("Server didn't start up in 2 seconds")
    }
    Sys.sleep(0.1)
  }

  r
}`

const rtdal002667Source0009 = `test_that("runStaticServer() in foreground with custom port", {
  port <- randomPort()

  r <- start_example_server(port)
  on.exit(
    {
      r$kill()
    },
    add = TRUE
  )

  expect_example_site(port)
})`

const rtdal002667Source0010 = `test_that("runStaticServer() in foreground with default port", {
  skip_if_not(is_port_available(7446))

  r <- start_example_server(NULL)
  on.exit(
    {
      r$kill()
    },
    add = TRUE
  )

  expect_example_site(7446)
})`

const rtdal002667Source0011 = `test_that("runStaticServer() throws an error for invalid ports", {
  on.exit({
    stopAllServers()
  }) # in case of a test failure

  expect_error(
    runStaticServer(path_example_site(), port = 0, background = TRUE)
  )
  expect_error(
    runStaticServer(path_example_site(), port = 700:720, background = TRUE)
  )
  expect_error(
    runStaticServer(path_example_site(), port = 74469, background = TRUE)
  )
  expect_error(
    runStaticServer(path_example_site(), port = "1234", background = TRUE)
  )
})`

const rtdal002667Source0012 = `test_that("runStaticServer() throws an error if the requested port is used", {
  on.exit({
    stopAllServers()
  }) # in case of a test failure

  s1 <- runStaticServer(path_example_site(), background = TRUE, browse = FALSE)

  expect_error(
    runStaticServer(
      path_example_site(),
      port = s1$getPort(),
      background = TRUE,
      browse = FALSE
    )
  )
})`

const rtdal002667Source0013 = `test_that("runStaticServer() in background uses default port", {
  skip_if_not(is_port_available(7446))

  s <- runStaticServer(path_example_site(), background = TRUE, browse = FALSE)
  on.exit(
    {
      stopServer(s)
    },
    add = TRUE
  )

  expect_example_site(7446)
})`

const rtdal002667Source0014 = `test_that("runStaticServer() in background uses default port or random port", {
  skip_if_not(is_port_available(7446))

  s1 <- runStaticServer(path_example_site(), background = TRUE, browse = FALSE)
  on.exit(
    {
      s1$stop()
    },
    add = TRUE
  )

  s2 <- runStaticServer(path_example_site(), background = TRUE, browse = FALSE)
  on.exit(
    {
      s2$stop()
    },
    add = TRUE
  )

  expect_example_site(7446)
  expect_example_site(s2$getPort())
})`

const rtdal002667Source0015 = `test_that("runStaticServer() in background errors if requested port is in use", {
  s1 <- runStaticServer(path_example_site(), background = TRUE, browse = FALSE)
  on.exit(
    {
      s1$stop()
    },
    add = TRUE
  )

  used_port <- s1$getPort()

  expect_error({
    s2 <- runStaticServer(
      path_example_site(),
      port = used_port,
      background = TRUE,
      browse = FALSE
    )
    s2$stop() # clean up in case test fails
  })
})`

const rtdal002667Source0016 = `test_that("runStaticServer() prints informative console messages", {
  local_edition(3)

  expect_snapshot(
    {
      s <- runStaticServer(
        path_example_site(),
        background = TRUE,
        browse = FALSE
      )
      s$stop()
    },
    transform = function(x) {
      sub(path_example_site(), "/Users/user/path/to/site", x, fixed = TRUE)
    }
  )
})`

