const rtdal002668Source0002 = `parse_ab_output <- function(p) {
  text <- readLines(p$get_output_file())

  if (!any(grepl("^Complete requests:\\s+", text))) {
    return(list(
      completed = NULL,
      failed = NULL,
      hang = TRUE,
      text = text
    ))
  }

  results <- list(
    hang = FALSE,
    text = text
  )

  line <- text[grepl("^Complete requests:\\s+", text)]
  results$completed <- as.integer(sub(
    "^Complete requests:\\s+(\\d+).*",
    "\\1",
    line
  ))

  line <- text[grepl("^Failed requests:\\s+", text)]
  results$failed <- as.integer(sub(
    "^Failed requests:\\s+(\\d+).*",
    "\\1",
    line
  ))

  results
}`

const rtdal002668Source0003 = `start_app <- function(port) {
  outfile <- tempfile()
  callr::r_bg(
    function(app_port) {
      source(testthat::test_path('sample_app.R'), local = TRUE)
      service(Inf)
    },
    args = list(app_port = port),
    stdout = outfile,
    stderr = outfile,
    supervise = TRUE
  )
}`

const rtdal002668Source0004 = `start_ab <- function(port, path, n = 400, concurrent = 100) {
  outfile <- tempfile()
  callr::process$new(
    "ab",
    args = c(
      paste0("-n", n),
      paste0("-c", concurrent),
      sprintf("http://127.0.0.1:%d%s", port, path)
    ),
    stdout = outfile,
    stderr = outfile
  )
}`

