const rtdal002735Source0002 = `round_trip <- function(...) {
  skip_httpbin()
  content(POST("http://httpbin.org/post", ...))
}`

const rtdal002735Source0005 = `test_that("NULL body gives empty data element", {
  out <- round_trip(body = NULL)
  expect_equal(out$data, "")
})`

const rtdal002735Source0006 = `test_that("FALSE body doesn't send body", {
  out <- round_trip(body = FALSE)
  expect_equal(out$data, NULL)
})`

const rtdal002735Source0007 = `test_that("string/raw in body gives same string in data element", {
  out <- round_trip(body = "test")
  expect_equal(out$data, "test")

  out <- round_trip(body = charToRaw("test"))
  expect_equal(out$data, "test")
})`

const rtdal002735Source0008 = "test_that(\"string/raw in body doesn't lose content type\", {\n  skip_httpbin()\n\n  body <- charToRaw(\"test\")\n  content_type <- \"application/awesome\"\n  response <- content(POST(\"http://httpbin.org/post\",\n    body = body,\n    add_headers(\"Content-Type\" = content_type)\n  ))\n  expect_equal(response$headers$`Content-Type`, content_type)\n})"

const rtdal002735Source0009 = `test_that("empty list gives empty body", {
  out <- round_trip(body = list(), encode = "form")
  expect_equal(out$data, "")

  out <- round_trip(body = list(), encode = "multipart")
  expect_equal(out$data, "")
})`

const rtdal002735Source0010 = `test_that("named list matches form results (encode = 'form')", {
  out <- round_trip(body = list(a = 1, b = 2), encode = "form")
  expect_equal(out$form$a, "1")
  expect_equal(out$form$b, "2")
})`

const rtdal002735Source0011 = `test_that("named list matches form results (encode = 'multipart')", {
  out <- round_trip(body = list(a = 1, b = 2), encode = "multipart")
  expect_equal(out$form$a, "1")
  expect_equal(out$form$b, "2")
})`

const rtdal002735Source0012 = `test_that("named list matches form results (encode = 'json')", {
  out <- round_trip(body = list(a = 1, b = 2), encode = "json")
  expect_equal(out$json$a[[1]], 1)
  expect_equal(out$json$b[[1]], 2)
})`

const rtdal002735Source0013 = `test_that("decimal precision is preserved (encode = 'json')", {
  out <- round_trip(
    body = list(a = 0.8675309867530986753098675309),
    encode = "json"
  )
  expect_equal(out$data, "{\"a\":0.867530986753099}")
})`

const rtdal002735Source0014 = `test_that("can do own encoding", {
  out <- round_trip(body = '{"a":1,"b":2}', content_type_json(), encode = "raw")
  expect_equal(out$json, list(a = 1, b = 2))
})`

const rtdal002735Source0015 = `test_that("NULL elements are automatically dropped", {
  out <- round_trip(body = list(x = 1, y = NULL), encode = "form")
  expect_equal(out$form, list(x = "1"))

  out <- round_trip(body = list(x = 1, y = NULL), encode = "multipart")
  expect_equal(out$form, list(x = "1"))
})`

const rtdal002735Source0016 = `test_that("file and form vals mixed give form and data elements", {
  out <- round_trip(body = list(y = data_path, a = 1))
  expect_equal(out$form$a, "1")
  expect_equal(strsplit(out$files$y, "\r?\n")[[1]], data)
})`

