const rtdal002769Source0001 = `oauth_client <- function(
  id,
  token_url = NULL,
  secret = NULL,
  key = NULL,
  auth = c("body", "header", "jwt_sig"),
  auth_params = list(),
  name = hash(id),
  metadata = NULL
) {
  check_string(id)

  auth_url <- NULL
  device_auth_url <- NULL
  if (!is.null(metadata)) {
    oauth_metadata_check(metadata)
    token_url <- token_url %||% metadata$token_endpoint
    auth_url <- metadata$authorization_endpoint
    device_auth_url <- metadata$device_authorization_endpoint
  }

  if (is.null(token_url)) {
    cli::cli_abort(
      "Must supply {.arg token_url}, or {.arg metadata} that advertises a {.field token_endpoint}."
    )
  }
  check_string(token_url)
  check_string(secret, allow_null = TRUE)

  if (is.character(auth)) {
    if (missing(auth)) {
      auth <- if (is.null(key)) "body" else "jwt_sig"
    }
    auth <- arg_match(auth)

    if (auth == "header" && is.null(secret)) {
      cli::cli_abort("{.code auth = 'header'} requires a {.arg secret}.")
    } else if (auth == "jwt_sig") {
      if (is.null(key)) {
        cli::cli_abort("{.code auth = 'jwt_sig'} requires a {.arg key}.")
      }
    }

    auth <- paste0("oauth_client_req_auth_", auth)
  } else if (!is_function(auth)) {
    cli::cli_abort("{.arg auth} must be a string or function.")
  }

  structure(
    list(
      name = name,
      id = id,
      secret = secret,
      key = key,
      token_url = token_url,
      auth_url = auth_url,
      device_auth_url = device_auth_url,
      auth = auth,
      auth_params = auth_params
    ),
    class = "httr2_oauth_client"
  )
}`

const rtdal002769Source0002 = `print.httr2_oauth_client <- function(x, ...) {
  cli::cat_line(cli::style_bold("<", paste(class(x), collapse = "/"), ">"))
  redacted <- list_redact(compact(x), c("secret", "key"))
  bullets(redacted)
  invisible(x)
}`

const rtdal002769Source0006 = `oauth_client_req_auth_jwt_sig <- function(
  req,
  client,
  claim = NULL,
  size = 256,
  header = list()
) {
  if (is.null(claim)) {
    cli::cli_abort(
      "{.code auth = 'jwt_sig'} requires a {.arg claim} in {.arg auth_params}."
    )
  }
  claim <- as_jwt_claim(claim)
  jwt <- jwt_encode_sig(claim, key = client$key, size = size, header = header)

  # https://datatracker.ietf.org/doc/html/rfc7523#section-2.2
  req_body_form(
    req,
    client_assertion = jwt,
    client_assertion_type = "urn:ietf:params:oauth:client-assertion-type:jwt-bearer"
  )
}`

const rtdal002769Source0007 = `oauth_flow_url <- function(url, client, field, call = caller_env()) {
  url <- url %||% client[[field]]
  if (is.null(url)) {
    cli::cli_abort(
      c(
        "Must supply {.arg auth_url}.",
        i = "Either pass it directly or set it on the {.arg client}, e.g. with {.fn oauth_server_metadata}."
      ),
      call = call
    )
  }
  url
}`

const rtdal002769Source0008 = `oauth_flow_check <- function(
  flow,
  client,
  is_confidential = FALSE,
  interactive = FALSE,
  error_call = caller_env()
) {
  if (!inherits(client, "httr2_oauth_client")) {
    cli::cli_abort(
      "{.arg client} must be an OAuth client created with {.fn oauth_client}.",
      call = error_call
    )
  }

  if (is_confidential && is.null(client$secret) && is.null(client$key)) {
    cli::cli_abort(
      c(
        "Can't use this {.arg app} with OAuth 2.0 {flow} flow.",
        i = "{.arg app} must have a confidential client (i.e. {.arg client_secret} is required)."
      ),
      call = error_call
    )
  }

  if (interactive && !is_interactive()) {
    cli::cli_abort(
      "OAuth 2.0 {flow} flow requires an interactive session",
      call = error_call
    )
  }
}`

const rtdal002769Source0009 = `oauth_client_get_token <- function(
  client,
  grant_type,
  ...,
  error_call = caller_env()
) {
  req <- request(client$token_url)
  req <- req_body_form(req, grant_type = grant_type, ...)
  req <- oauth_client_req_auth(req, client)
  req <- req_headers(req, Accept = "application/json")

  resp <- oauth_flow_fetch(req, "client$token_url", error_call = error_call)
  exec(oauth_token, !!!resp)
}`

