const rtdal002797Source0001 = `req_perform_connection <- function(
  req,
  blocking = TRUE,
  verbosity = NULL,
  mock = getOption("httr2_mock", NULL)
) {
  check_request(req)
  check_bool(blocking)
  req <- req_verbosity_connection(req, verbosity %||% httr2_verbosity())
  req <- req_policies(req, connection = TRUE)

  if (!is.null(mock)) {
    mock <- as_function(mock)
    mock_resp <- mock(req)
    if (!is.null(mock_resp)) {
      return(handle_resp(req, mock_resp))
    }
  }

  req_prep <- req_prepare(req)
  handle <- req_handle(req_prep)
  the$last_request <- req
  the$last_response <- NULL

  tries <- 0
  delay <- 0
  max_tries <- retry_max_tries(req)
  deadline <- Sys.time() + retry_max_seconds(req)
  resp <- NULL
  while (tries < max_tries && Sys.time() < deadline) {
    retry_check_breaker(req, tries)
    sys_sleep(delay, "for retry backoff")

    if (is_response(resp)) {
      close(resp)
    }
    resp <- req_perform_connection1(
      req,
      req_prep,
      handle,
      blocking = blocking,
      resend_count = tries + 1L
    )

    if (retry_is_transient(req, resp)) {
      tries <- tries + 1

      delay <- retry_after(req, resp, tries)
      signal(class = "httr2_retry", tries = tries, delay = delay)
    } else {
      break
    }
  }
  req_completed(req_prep)

  if (!is_error(resp) && error_is_error(req, resp)) {
    # Read full body if there's an error
    resp$body <- resp$body$read_all()
    the$last_response <- resp
  }
  handle_resp(req, resp)

  resp
}`

const rtdal002797Source0002 = `req_verbosity_connection <- function(
  req,
  verbosity,
  error_call = caller_env()
) {
  if (!is_integerish(verbosity, n = 1) || verbosity < 0 || verbosity > 3) {
    cli::cli_abort("{.arg verbosity} must 0, 1, 2, or 3.", call = error_call)
  }

  req <- switch(
    verbosity + 1,
    req,
    req_verbose(req),
    req_verbose(req, body_req = TRUE),
    req_verbose(req, body_req = TRUE, info = TRUE)
  )
  if (verbosity > 1) {
    req <- req_policies(
      req,
      show_streaming_body = verbosity >= 2,
      show_streaming_buffer = verbosity >= 3
    )
  }
  req
}`

const rtdal002797Source0003 = `req_perform_connection1 <- function(
  req,
  req_prep,
  handle,
  blocking = TRUE,
  resend_count = 0
) {
  the$last_request <- req
  the$last_response <- NULL
  signal(class = "httr2_perform_connection")
  # Note: we need to do this before we call handle_preflight() so that request
  # signing works correctly with the added headers.
  req_prep <- req_with_span(req_prep, resend_count = resend_count)
  handle_preflight(req_prep, handle)

  err <- capture_curl_error({
    conn <- curl::curl(req$url, handle = handle)
    # Must open the stream in order to initiate the connection
    suppressWarnings(open(conn, "rbf", blocking = blocking))
    body <- StreamingBody$new(conn)
  })
  if (is_error(err)) {
    req_record_span_status(req, err)
    close(conn)
    return(err)
  }

  curl_data <- curl::handle_data(handle)
  resp <- create_response(req, curl_data, body)
  req_record_span_status(req, resp)
  resp
}`

const rtdal002797Source0005 = "StreamingBody <- R6::R6Class(\n  \"StreamingBody\",\n  public = list(\n    #' @description Create a new object\n    #' @param conn A connection, that is open and ready for reading.\n    #'   `StreamingBody` will take care of closing it.`\n    initialize = function(conn) {\n      if (!inherits(conn, \"connection\")) {\n        stop_input_type(conn, \"a connection\", call = caller_env())\n      }\n      private$conn <- conn\n    },\n\n    #' @description Read `n` bytes into a raw vector.\n    #' @param n Number of bytes to read\n    read = function(n) {\n      readBin(private$conn, \"raw\", n)\n    },\n\n    #' @description Read all bytes and close the connection.\n    #' @param buffer Buffer size, in bytes.\n    read_all = function(buffer = 32 * 1024) {\n      bytes <- raw()\n      repeat {\n        new <- self$read(buffer)\n        if (length(new) == 0) {\n          break\n        }\n        bytes <- c(bytes, new)\n      }\n\n      self$close()\n      if (length(bytes) == 0) {\n        NULL\n      } else {\n        bytes\n      }\n    },\n\n    #' @description Is the connection still open?\n    is_open = function() {\n      isValid(private$conn)\n    },\n\n    #' @description Is the connection complete? (i.e. is there data remaining\n    #'   to be read?)\n    is_complete = function() {\n      !isIncomplete(private$conn)\n    },\n\n    #' @description Get the active file descriptions and timeout from the\n    #'   handle. Wrapper around [curl::multi_fdset()].\n    get_fdset = function() {\n      curl::multi_fdset(private$conn)\n    },\n\n    #' @description Close the connection\n    close = function() {\n      if (self$is_open()) {\n        close(private$conn)\n      }\n    }\n  ),\n  private = list(\n    conn = NULL\n  )\n)"

