const rtdal002803Source0003 = `req_policy_call <- function(req, name, args, default) {
  if (req_policy_exists(req, name)) {
    exec(req$policies[[name]], !!!args)
  } else {
    if (is_function(default)) {
      exec(default, !!!args)
    } else {
      default
    }
  }
}`

const rtdal002803Source0004 = `as_callback <- function(x, n, name, error_call = caller_env()) {
  if (is.null(x)) {
    return(x)
  }

  x <- as_function(x)
  if (!inherits(x, "rlang_lambda_function") && length(formals(x)) != n) {
    cli::cli_abort(
      "Callback {.fn name} must have {n} argument{?s}",
      call = error_call
    )
  }
  x
}`

