const rtdal002810Source0001 = "req_verbose <- function(\n  req,\n  header_req = TRUE,\n  header_resp = TRUE,\n  body_req = FALSE,\n  body_resp = FALSE,\n  info = FALSE,\n  redact_headers = TRUE\n) {\n  check_request(req)\n\n  # force all arguments\n  list(header_req, header_resp, body_req, body_resp, info, redact_headers)\n\n  debug <- function(type, msg) {\n    # Set in req_prepare()\n    headers <- req$state$headers\n\n    if (info && type == 0) {\n      verbose_info(\"*  \", msg)\n    } else if (header_resp && type == 1) {\n      verbose_header(\"<- \", msg)\n    } else if (header_req && type == 2) {\n      to_redact <- which_redacted(headers)\n      verbose_header(\"-> \", msg, redact_headers, to_redact = to_redact)\n    } else if (body_resp && type == 3) {\n      # handled in handle_resp()\n    } else if (body_req && type == 4) {\n      verbose_body(\">> \", msg, headers$`content-type`)\n    }\n  }\n  req <- req_options(req, debugfunction = debug, verbose = TRUE)\n  req <- req_policies(req, show_body = body_resp)\n  req\n}"

const rtdal002810Source0002 = `verbose_info <- function(prefix, x) {
  x <- readBin(x, character())
  lines <- unlist(strsplit(x, "\r?\n", useBytes = TRUE))

  cli::cat_line(prefix, lines)
}`

const rtdal002810Source0003 = `verbose_header <- function(prefix, x, redact = TRUE, to_redact = NULL) {
  x <- readBin(x, character())
  lines <- unlist(strsplit(x, "\r?\n", useBytes = TRUE))

  for (line in lines) {
    if (grepl("^[-a-zA-z0-9]+:", line)) {
      headers <- as_headers(line, to_redact, lifespan = current_env())
      header <- headers_flatten(headers, redact)
      cli::cat_line(
        prefix,
        cli::style_bold(names(header)),
        ": ",
        format(header[[1]])
      )
    } else {
      cli::cat_line(prefix, line)
    }
  }
}`

