const rtdal002816Source0001 = `resp_stream_aws <- function(resp, max_size = Inf) {
  splitter <- init_streaming_response(resp, AwsSplitter)
  check_number_whole(max_size, min = 1, allow_infinite = TRUE)

  blocks <- stream_pull(resp, 1, splitter, max_size)
  if (length(blocks) == 0L) {
    return()
  }
  event_bytes <- blocks[[1L]]

  event <- parse_aws_event(event_bytes)
  if (resp_stream_show_body(resp)) {
    # Emit header
    for (key in names(event$headers)) {
      log_stream(cli::style_bold(key), ": ", event$headers[[key]])
    }
    # Emit body
    log_stream(jsonlite::toJSON(event$body, auto_unbox = TRUE, pretty = TRUE))
    cli::cat_line()
  }
  event
}`

const rtdal002816Source0002 = `AwsSplitter <- R6::R6Class(
  "AwsSplitter",
  inherit = StreamSplitter,
  public = list(
    name = "resp_stream_aws()",
    find_boundaries = function(buffer) find_aws_event_boundaries(buffer)
  )
)`

const rtdal002816Source0004 = "parse_aws_event <- function(bytes) {\n  i <- 1\n  read_bytes <- function(n) {\n    if (n == 0) {\n      return(raw())\n    }\n    out <- bytes[i:(i + n - 1)]\n    i <<- i + n\n    out\n  }\n\n  # prelude\n  total_length <- parse_int(read_bytes(4))\n  if (total_length != length(bytes)) {\n    cli::cli_abort(\n      \"AWS event metadata doesn't match supplied bytes\",\n      .internal = TRUE\n    )\n  }\n\n  header_length <- parse_int(read_bytes(4))\n  prelude_crc <- read_bytes(4)\n  # TODO: use this value to check prelude lengths\n\n  # headers\n  headers <- list()\n  while (i <= 12 + header_length) {\n    name_length <- as.integer(read_bytes(1))\n    name <- rawToChar(read_bytes(name_length))\n    type <- as.integer(read_bytes(1))\n\n    delayedAssign(\"length\", parse_int(read_bytes(2)))\n    value <- switch(\n      type_enum(type),\n      \"TRUE\" = TRUE,\n      \"FALSE\" = FALSE,\n      BYTE = parse_int(read_bytes(1), signed = TRUE),\n      SHORT = parse_int(read_bytes(2), signed = TRUE),\n      INTEGER = parse_int(read_bytes(4), signed = TRUE),\n      LONG = parse_int64(read_bytes(8)),\n      BYTE_ARRAY = read_bytes(length),\n      CHARACTER = rawToChar(read_bytes(length)),\n      TIMESTAMP = parse_int64(read_bytes(8)),\n      UUID = raw_to_hex(read_bytes(16)),\n    )\n    headers[[name]] <- value\n  }\n\n  # body\n  body_raw <- read_bytes(total_length - i - 4 + 1)\n  crc_raw <- read_bytes(4)\n  # TODO: use this value to check data\n\n  body <- rawToChar(body_raw)\n  if (identical(headers$`:content-type`, \"application/json\")) {\n    body <- jsonlite::parse_json(body)\n  }\n\n  list(headers = headers, body = body)\n}"

const rtdal002816Source0006 = `parse_int64 <- function(x) {
  y <- readBin(x, "double", n = 1, size = length(x), endian = "big")
  class(y) <- "integer64"
  y
}`

const rtdal002816Source0007 = `type_enum <- function(value) {
  if (value < 0 || value > 9) {
    cli::cli_abort("Unsupported type {value}.", .internal = TRUE)
  }

  switch(
    value + 1,
    "TRUE",
    "FALSE",
    "BYTE",
    "SHORT",
    "INTEGER",
    "LONG",
    "BYTE_ARRAY",
    "CHARACTER",
    "TIMESTAMP",
    "UUID"
  )
}`

